// Parse the Rattle alert: pull the Opportunity Name, channel and thread ts.
const m = $input.item.json;
const text = m.text || '';

// '*Name:* Branch | Winback | 6 - 2026'  -> 'Branch | Winback | 6 - 2026'
const nameMatch = text.match(/\*Name:\*\s*(.+)/);
if (!nameMatch) {
  throw new Error('No *Name:* line found in Rattle message.');
}
let name = nameMatch[1].trim();
// strip any surrounding angle-bracket slack link wrapper, if present
name = name.replace(/^<https?:[^|]+\|/, '').replace(/>$/, '').trim();

return {
  opp_name: name,
  soql_name: name.replace(/'/g, "\\'"),
  channel: m.channel,
  thread_ts: m.thread_ts || m.ts,
  raw_text: text
};

// Assemble the worker payload. n8n fetched the SF data (its OAuth2 user has
// Opportunity access), so the worker won't query Salesforce itself.
const parse = $('Parse deal').item.json;
const opp = $('SF: Opportunity').item.json.records || [];
const lines = $('SF: Line Items').item.json.records || [];
const contracts = $('SF: Contracts').item.json.records || [];

return {
  channel_id: parse.channel,
  thread_ts: parse.thread_ts,
  text: parse.raw_text,
  sf: {
    opp: opp[0] || null,
    lineItems: lines,
    contracts: contracts
  }
};
